INSERT OR REPLACE INTO findings (doc, title, date, verdict, superseded_by, summary) VALUES (101, 'Ignition v1 US-hours variant: a fifth of the trades, half the profit, +9.2 pts/trade', '2026-10-20', 'confirmed', NULL, '12 months 5-min NQ: all sessions 697 trades +3.52 pts/trade (t 2.5, shadow +0.30); US cash hours 13:30-20:00 UTC only 128 trades +9.16 pts/trade (t 2.5, win 77%, shadow -1.55). Clears IG''s ~1 pt in-hours spread by 9x. Runs in paperbook7 shadow from 20 Oct as the IG candidate (equity_us).');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, superseded_by, summary) VALUES (101, 'Daily long-only books at Coinbase Advanced base fees (60 bps/side)', '2026-10-20', 'confirmed', NULL, 'Golden-cross v1: +1.18%/ep at 4.5 bps -> -0.52%/ep at 60 bps (win 39%, 30% of coins positive). Dead on Coinbase. Pattern engine crypto daily: BTC>EMA200 gate +3.34%/trade net (n 1,733, t 10.2, win 64%, avg stop 14%); + lower third of year +7.36%/trade (n 372, t 10.6, win 80%). Survives. Edge over random same-R:R longs ~0.1R = ~1.4%/trade; the rest is BTC-bull beta.');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (176, 'Coinbase (spot, unlevered, long only) hosts only the daily pattern engine with the BTC>EMA200 gate; Golden-cross v1 is not a Coinbase candidate. Ignition v1 goes to IG only in its US-hours form.', 'doc 101 fee re-run and US-hours cut', 101, '2026-10-20');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, superseded_by, summary) VALUES (105, 'NYO / session-structure study on BTC: structure is near-certain, direction is not', '2026-10-20', 'confirmed', NULL, '1,304 weekdays. London extreme swept in NY 95% (median 30 min); first 30-min move retraces the open 81%; NY runs London AND Asia on the same side 87%; nearest side first 77% (96% from the bottom fifth of the overnight range); side taken first = session close side 70% (89% when the far side went first). Previous day, weekday, Asia->NY direction: no information. Weekend: pump/dump folklore; weekend levels taken on Monday 74%/68%, Sunday close position predicts which 80-85%.');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, superseded_by, summary) VALUES (105, 'Static levels carry no measurable information on BTC', '2026-10-20', 'rejected', NULL, 'Rule-drawn rising diagonals (615 touches, 222 breaks, 70 reclaims): touch-and-hold next 3d up 49%, reclaim 51%, breaks not followed by downside; no t above 1.1. With confluence (session extreme / swing low / fib): holds 3d 35-40%, up 41-49%; 2+ reasons 7d mean +1.6% vs +0.4% base (n 72), ~2 SE, tracked not used. Horizontal swing-low retests (n 360): holds 45%, 7d -0.41%. Fib 38/50/62 pullbacks (n 250-303): holds 37-41%, within noise. First-30-min fade rule: hit 28%, edge -0.007%, rejected.');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (177, 'An NYO book is an Asia-box resolution book: overnight box + side (open position, London lean, Sunday close on Mondays) + FLOW AT THE WALL. Static levels (diagonals, horizontals, fibs) are not inputs on their own; confluence of 2+ reasons is tracked as a possible filter only.', 'doc 105 sections C, F, I; levels tests', 105, '2026-10-20');
